import { useEffect, Suspense, useState } from 'react';
import { createBrowserRouter, RouterProvider } from 'react-router-dom';

import ReloadPrompt from './components/common/ReloadPrompt';
import { ToastContainer } from './components/common/Toast';
import Footer from './components/Footer';
import Navigation from './components/Navigation';
import { DesignTokenProvider } from './contexts/DesignTokenContext';
import { cleanupSupabase } from './lib/supabase/client';
import Routes from './Routes';

// Prefetch theme from localStorage to prevent flash
const getInitialTheme = () => {
  if (typeof window !== 'undefined') {
    const savedTheme = localStorage.getItem('theme');
    if (savedTheme) return savedTheme === 'dark';
    return window.matchMedia('(prefers-color-scheme: dark)').matches;
  }
  return false;
};

const router = createBrowserRouter([{ path: '*', Component: Layout }]);

function Layout() {
  const [isDark, setIsDark] = useState(getInitialTheme);
  const [isMenuOpen, setIsMenuOpen] = useState(false);

  // Save theme preference whenever it changes
  useEffect(() => {
    localStorage.setItem('theme', isDark ? 'dark' : 'light');
    // Also update system UI if supported
    if (isDark) {
      document.documentElement.classList.add('dark');
    } else {
      document.documentElement.classList.remove('dark');
    }
  }, [isDark]);

  // Listen for system theme changes
  useEffect(() => {
    const mediaQuery = window.matchMedia('(prefers-color-scheme: dark)');
    const handleChange = (e: MediaQueryListEvent) => {
      const hasThemePreference = localStorage.getItem('theme');
      if (!hasThemePreference) {
        setIsDark(e.matches);
      }
    };

    mediaQuery.addEventListener('change', handleChange);
    return () => {
      mediaQuery.removeEventListener('change', handleChange);
      cleanupSupabase();
    };
  }, []);

  return (
    <DesignTokenProvider>
      <div className={isDark ? 'dark' : ''}>
        <div className="min-h-screen bg-white dark:bg-gray-900 transition-colors duration-300">
          <Navigation
            isDark={isDark}
            setIsDark={setIsDark}
            isMenuOpen={isMenuOpen}
            setIsMenuOpen={setIsMenuOpen}
          />
          <Suspense fallback={<div />}>
            <Routes />
          </Suspense>
          <Footer />
          <ToastContainer />
          <ReloadPrompt />
        </div>
      </div>
    </DesignTokenProvider>
  );
}

export default function App() {
  return <RouterProvider router={router} />;
}
