import type { Metric } from 'web-vitals';

function sendToAnalytics(metric: Metric) {
  // Log to console in development for debugging
  if (import.meta.env.DEV) {
    console.log(`[Web Vitals] ${metric.name}: ${metric.value.toFixed(1)} (${metric.rating})`);
    return;
  }

  // In production, use sendBeacon for reliable delivery
  // NOTE: No analytics endpoint configured yet (future phase).
  // For now, log to console in production too so metrics are visible
  // in browser DevTools during manual testing.
  console.log(`[Web Vitals] ${metric.name}: ${metric.value.toFixed(1)} (${metric.rating})`);
}

export function reportWebVitals() {
  // Dynamic import to avoid blocking main bundle
  import('web-vitals').then(({ onCLS, onFCP, onINP, onLCP, onTTFB }) => {
    onFCP(sendToAnalytics);
    onLCP(sendToAnalytics);
    onCLS(sendToAnalytics);
    onINP(sendToAnalytics);
    onTTFB(sendToAnalytics);
  });
}
