import { useCallback } from 'react';

import { useEventListener } from '../lib/events';
import { supabase } from '../lib/supabase/client';
import type { Database } from '../lib/supabase/types';

import { useSupabaseQuery } from './useSupabaseQuery';

export type DesignToken = Database['public']['Tables']['design_tokens']['Row'];

export function useDesignTokens() {
  const {
    data: tokens,
    isLoading,
    refetch,
  } = useSupabaseQuery(
    async () => {
      const { data, error } = await supabase
        .from('design_tokens')
        .select('*')
        .order('category', { ascending: true });
      if (error) throw error;
      return (data || []) as DesignToken[];
    },
    { initialData: [] as DesignToken[] }
  );

  useEventListener(
    'design_tokens-updated',
    useCallback(() => refetch(), [refetch])
  );

  const tokenMap = tokens.reduce<Record<string, string>>((acc, t) => {
    acc[t.name] = t.value;
    return acc;
  }, {});

  return { tokens, tokenMap, isLoading };
}
