import { supabase } from '../lib/supabase/client';
import type { Article, Project, ContentRow } from '../types/common';

import { stripContentPrefix } from './contentId';

export async function getArticles(): Promise<Article[]> {
  const { data, error } = await supabase
    .from('content')
    .select('*')
    .eq('type', 'article')
    .eq('published', true)
    .order('date', { ascending: false });

  if (error) throw error;
  return (data || []).map(transformArticle);
}

export async function getArticle(id: string): Promise<Article | null> {
  const { data, error } = await supabase
    .from('content')
    .select('*')
    .eq('id', `article_${id}`)
    .eq('type', 'article')
    .eq('published', true)
    .single();

  if (error) throw error;
  if (!data) return null;

  return transformArticle(data);
}

export async function getProjects(): Promise<Project[]> {
  const { data, error } = await supabase
    .from('content')
    .select('*')
    .eq('type', 'project')
    .eq('published', true)
    .order('priority', { ascending: true })
    .order('date', { ascending: false });

  if (error) throw error;
  return (data || []).map(transformProject);
}

export async function getProject(id: string): Promise<Project | null> {
  const { data, error } = await supabase
    .from('content')
    .select('*')
    .eq('id', `project_${id}`)
    .eq('type', 'project')
    .eq('published', true)
    .single();

  if (error) throw error;
  if (!data) return null;

  return transformProject(data);
}

export function transformArticle(data: ContentRow): Article {
  return {
    id: stripContentPrefix(data.id),
    title: data.title,
    publication: data.publication || '',
    date: data.date,
    description: data.description,
    link: data.link,
    type: data.type,
    tags: data.tags,
    priority: data.priority,
    image: data.image || undefined,
    video: data.video || undefined,
    keyPoints: data.key_points || undefined,
    mainContent: data.main_content || undefined,
    category: data.category || undefined,
    readTime: data.read_time || undefined,
    headline: data.headline || undefined,
    author: data.author_name
      ? {
          name: data.author_name,
          title: data.author_title || '',
          image: data.author_image || undefined,
        }
      : undefined,
  };
}

export function transformProject(data: ContentRow): Project {
  return {
    id: stripContentPrefix(data.id),
    title: data.title,
    client: data.client || '',
    description: data.description,
    link: data.link,
    tags: data.tags,
    priority: data.priority,
    image: data.image || '',
    date: data.date,
    keyPoints: data.key_points || undefined,
    mainContent: data.main_content || undefined,
    detailedDescription: data.description,
    headline: data.headline || undefined,
  };
}
