import { useState, useCallback, useRef, useEffect } from 'react';

import { supabase } from '../lib/supabase/client';
import type { Article, Project } from '../types/common';
import { transformArticle, transformProject } from '../utils/content';

interface SearchResults {
  articles: Article[];
  projects: Project[];
}

export function useSearch() {
  const [results, setResults] = useState<SearchResults>({ articles: [], projects: [] });
  const [isLoading, setIsLoading] = useState(false);
  const [error, setError] = useState<Error | null>(null);
  const abortControllerRef = useRef<AbortController | null>(null);

  const search = useCallback(async (query: string, type?: 'article' | 'project') => {
    if (!query.trim()) {
      setResults({ articles: [], projects: [] });
      return;
    }

    try {
      // Cancel any pending requests
      if (abortControllerRef.current) {
        abortControllerRef.current.abort();
      }

      // Create new abort controller for this request
      abortControllerRef.current = new AbortController();

      setIsLoading(true);
      setError(null);

      // Build search query
      let searchQuery = supabase
        .from('content')
        .select('*')
        .eq('published', true)
        .or(
          `title.ilike.%${query}%,description.ilike.%${query}%,main_content.ilike.%${query}%,headline.ilike.%${query}%,client.ilike.%${query}%,publication.ilike.%${query}%,author_name.ilike.%${query}%,author_title.ilike.%${query}%`
        );

      // Add type filter if specified
      if (type) {
        searchQuery = searchQuery.eq('type', type);
      }

      // Execute search
      const { data, error: searchError } = await searchQuery
        .order('priority', { ascending: true })
        .order('date', { ascending: false })
        .limit(10)
        .abortSignal(abortControllerRef.current.signal);

      if (searchError) {
        // Ignore abort errors as they're expected when cancelling
        if (searchError.message?.includes('aborted')) {
          return;
        }
        throw searchError;
      }

      if (!data) {
        setResults({ articles: [], projects: [] });
        return;
      }

      // Transform results using shared transform functions
      const articles = data.filter(item => item.type === 'article').map(transformArticle);
      const projects = data.filter(item => item.type === 'project').map(transformProject);

      setResults({ articles, projects });
      setError(null);
    } catch (err) {
      // Ignore abort errors
      if (err instanceof Error && err.name === 'AbortError') {
        return;
      }

      const error = err instanceof Error ? err : new Error('Search failed');
      console.error('Search error:', error);
      setError(error);
      setResults({ articles: [], projects: [] });
    } finally {
      setIsLoading(false);
    }
  }, []);

  // Cleanup abort controller on unmount
  useEffect(() => {
    return () => {
      if (abortControllerRef.current) {
        abortControllerRef.current.abort();
      }
    };
  }, []);

  return { search, results, isLoading, error };
}
