import { motion } from 'framer-motion';
import { Mail, Linkedin } from 'lucide-react';

import { useFooter } from '../hooks/useFooter';

export default function Footer() {
  const { footer, isLoading } = useFooter();

  if (isLoading || !footer) {
    return null;
  }

  const year = new Date().getFullYear().toString();
  const copyright = footer.copyright_text.replace('{year}', year);

  return (
    <footer className="bg-white dark:bg-gray-900 py-12 px-6">
      <div className="container mx-auto">
        <div className="flex flex-col md:flex-row justify-between items-center">
          <div className="mb-8 md:mb-0">
            <h3 className="text-3xl font-bold text-gray-900 dark:text-white mb-4">
              Let&apos;s Connect
            </h3>
            <div className="flex gap-4">
              <motion.a
                whileHover={{ scale: 1.1 }}
                whileTap={{ scale: 0.95 }}
                href={footer.social_links.linkedin}
                target="_blank"
                rel="noopener noreferrer"
                className="p-3 bg-white dark:bg-gray-800 rounded-full shadow-lg hover:shadow-xl transition-all"
              >
                <Linkedin className="w-6 h-6 text-gray-700 dark:text-gray-200" />
              </motion.a>
              <motion.a
                whileHover={{ scale: 1.1 }}
                whileTap={{ scale: 0.95 }}
                href={`mailto:${footer.social_links.email}`}
                className="p-3 bg-white dark:bg-gray-800 rounded-full shadow-lg hover:shadow-xl transition-all"
              >
                <Mail className="w-6 h-6 text-gray-700 dark:text-gray-200" />
              </motion.a>
            </div>
          </div>
          <p className="text-gray-600 dark:text-gray-400">{copyright}</p>
        </div>
      </div>
    </footer>
  );
}
