import { useEffect } from 'react';

export type RealtimePayload = {
  type: string;
  new: Record<string, unknown>;
  old: Record<string, unknown>;
};

export type EventMap = {
  'content-updated': RealtimePayload;
  'tags-updated': RealtimePayload;
  'skills-updated': RealtimePayload;
  'skill_categories-updated': RealtimePayload;
  'awards-updated': RealtimePayload;
  'design_tokens-updated': RealtimePayload;
};

export function emitEvent<K extends keyof EventMap>(event: K, detail: EventMap[K]): void {
  window.dispatchEvent(new CustomEvent(event, { detail }));
}

export function useEventListener<K extends keyof EventMap>(
  event: K,
  handler: (detail: EventMap[K]) => void
): void {
  useEffect(() => {
    const listener = (e: Event) => {
      handler((e as CustomEvent<EventMap[K]>).detail);
    };
    window.addEventListener(event, listener);
    return () => window.removeEventListener(event, listener);
  }, [event, handler]);
}
