import { motion } from 'framer-motion';
import { useNavigate, useLocation } from 'react-router-dom';

import { scrollToSection, scrollToTop } from '../../utils/scroll';

interface NavLinkProps {
  href: string;
  children: React.ReactNode;
  isActive: boolean;
  isMobile?: boolean;
  onClick?: () => void;
}

export default function NavLink({ href, children, isActive, isMobile, onClick }: NavLinkProps) {
  const navigate = useNavigate();
  const location = useLocation();

  const handleClick = (e: React.MouseEvent<HTMLAnchorElement>) => {
    e.preventDefault();

    if (href.startsWith('/#')) {
      const sectionId = href.substring(2);

      if (location.pathname !== '/') {
        // First navigate to home
        navigate('/', { replace: true });
        // Then scroll after a small delay to ensure the page has loaded
        setTimeout(() => {
          scrollToSection(sectionId);
        }, 100);
      } else {
        scrollToSection(sectionId);
      }
    } else {
      // For regular navigation, scroll to top and navigate
      scrollToTop();
      navigate(href);
    }

    if (onClick) onClick();
  };

  return (
    <motion.div whileHover={{ scale: 1.05 }} whileTap={{ scale: 0.95 }}>
      <a
        href={href}
        onClick={handleClick}
        className={`
          ${isMobile ? 'block py-2' : 'px-4 py-2 rounded-full'}
          ${
            isActive
              ? 'text-primary dark:text-primary-light font-medium'
              : 'text-gray-600 dark:text-gray-300 hover:text-primary dark:hover:text-primary-light'
          }
          transition-colors duration-300
        `}
      >
        <span className="relative">
          {children}
          {isActive && !isMobile && (
            <motion.span
              layoutId="active-indicator"
              className="absolute -bottom-1 left-0 right-0 h-0.5 bg-primary dark:bg-primary-light"
              transition={{ type: 'spring', bounce: 0.2, duration: 0.6 }}
            />
          )}
        </span>
      </a>
    </motion.div>
  );
}
