import { lazy, Suspense } from 'react';
import { Routes as RouterRoutes, Route } from 'react-router-dom';

import ErrorBoundary from './components/common/ErrorBoundary';
import LoadingSpinner from './components/common/LoadingSpinner';

// Lazy load route components with error boundaries
const HomePage = lazy(() => import('./pages/HomePage'));
const AboutPage = lazy(() => import('./pages/AboutPage'));
const ContentPage = lazy(() => import('./pages/ContentPage'));
const FilteredResultsPage = lazy(() => import('./pages/FilteredResultsPage'));
const TagManagementPage = lazy(() => import('./pages/TagManagementPage'));
const ErrorPage = lazy(() => import('./pages/ErrorPage'));

export default function Routes() {
  return (
    <ErrorBoundary>
      <Suspense fallback={<LoadingSpinner />}>
        <RouterRoutes>
          <Route path="/" element={<HomePage />} />
          <Route path="/about" element={<AboutPage />} />
          <Route path="/projects/:id" element={<ContentPage type="project" />} />
          <Route path="/articles/:id" element={<ContentPage type="article" />} />
          <Route path="/filtered" element={<FilteredResultsPage />} />
          <Route path="/filtered/:tag" element={<FilteredResultsPage />} />
          <Route path="/tag-management" element={<TagManagementPage />} />
          <Route path="*" element={<ErrorPage />} />
        </RouterRoutes>
      </Suspense>
    </ErrorBoundary>
  );
}
