import { createContext, useContext, useEffect, type ReactNode } from 'react';

import { useDesignTokens } from '../hooks/useDesignTokens';

interface DesignTokenState {
  tokenMap: Record<string, string>;
  isLoading: boolean;
}

const DesignTokenContext = createContext<DesignTokenState>({ tokenMap: {}, isLoading: true });

// CSS custom property names that map to token names
const TOKEN_CSS_MAP: Record<string, string> = {
  'color-primary': '--color-primary',
  'color-primary-light': '--color-primary-light',
  'color-primary-dark': '--color-primary-dark',
  'color-neutral-dark': '--color-neutral-dark',
  'color-neutral-darker': '--color-neutral-darker',
  'font-sans': '--font-sans',
  'font-title': '--font-title',
};

export function DesignTokenProvider({ children }: { children: ReactNode }) {
  const { tokenMap, isLoading } = useDesignTokens();

  // Inject CSS custom properties whenever tokens change
  useEffect(() => {
    let style = document.getElementById('design-tokens-style') as HTMLStyleElement | null;
    if (!style) {
      style = document.createElement('style');
      style.id = 'design-tokens-style';
      document.head.appendChild(style);
    }

    const declarations = Object.entries(tokenMap)
      .map(([name, value]) => {
        const cssVar = TOKEN_CSS_MAP[name];
        if (!cssVar) return null;
        return `  ${cssVar}: ${value};`;
      })
      .filter(Boolean)
      .join('\n');

    if (declarations) {
      style.textContent = `:root {\n${declarations}\n}`;
    }
  }, [tokenMap]);

  return (
    <DesignTokenContext.Provider value={{ tokenMap, isLoading }}>
      {children}
    </DesignTokenContext.Provider>
  );
}

export function useDesignTokenContext() {
  return useContext(DesignTokenContext);
}
