import { Loader2, FileText, FolderGit2 } from 'lucide-react';
import { Link } from 'react-router-dom';

import type { Article, Project } from '../../types/common';
import { scrollToTop } from '../../utils/scroll';

interface SearchResultsListProps {
  results: { articles: Article[]; projects: Project[] };
  isLoading: boolean;
  error: Error | null;
  query: string;
  selectedType: 'all' | 'article' | 'project';
  onClose: () => void;
}

export default function SearchResultsList({
  results,
  isLoading,
  error,
  query,
  selectedType,
  onClose,
}: SearchResultsListProps) {
  const totalResults = results.articles.length + results.projects.length;

  return (
    <div className="overflow-y-auto overscroll-contain" style={{ maxHeight: 'calc(85vh - 116px)' }}>
      {isLoading ? (
        <div className="p-8 text-center">
          <Loader2 className="w-6 h-6 animate-spin text-primary dark:text-primary-light mx-auto mb-2" />
          <p className="text-neutral-dark/70 dark:text-white/70">Searching...</p>
        </div>
      ) : error ? (
        <div className="p-8 text-center">
          <p className="text-red-500 dark:text-red-400">{error.message}</p>
        </div>
      ) : query && totalResults === 0 ? (
        <div className="p-8 text-center">
          <p className="text-neutral-dark/70 dark:text-white/70">
            No results found for &ldquo;{query}&rdquo;
          </p>
        </div>
      ) : (
        <div className="divide-y divide-gray-200 dark:divide-gray-800">
          {(selectedType === 'all' || selectedType === 'article') &&
            results.articles.length > 0 && (
              <div className="p-4">
                <h3 className="text-sm font-medium text-neutral-dark/70 dark:text-white/70 mb-2">
                  Articles
                </h3>
                <div className="space-y-2">
                  {results.articles.map(article => (
                    <Link
                      key={article.id}
                      to={`/articles/${article.id}`}
                      onClick={() => {
                        onClose();
                        scrollToTop();
                      }}
                      className="block p-3 rounded-lg hover:bg-gray-100 dark:hover:bg-gray-800 transition-colors active:bg-gray-200 dark:active:bg-gray-700"
                    >
                      <div className="flex items-start gap-3">
                        <FileText className="w-5 h-5 text-primary dark:text-primary-light flex-shrink-0 mt-1" />
                        <div>
                          <h4 className="font-medium text-neutral-dark dark:text-white mb-1">
                            {article.title}
                          </h4>
                          <p className="text-sm text-neutral-dark/70 dark:text-white/70 line-clamp-2">
                            {article.description}
                          </p>
                        </div>
                      </div>
                    </Link>
                  ))}
                </div>
              </div>
            )}

          {(selectedType === 'all' || selectedType === 'project') &&
            results.projects.length > 0 && (
              <div className="p-4">
                <h3 className="text-sm font-medium text-neutral-dark/70 dark:text-white/70 mb-2">
                  Projects
                </h3>
                <div className="space-y-2">
                  {results.projects.map(project => (
                    <Link
                      key={project.id}
                      to={`/projects/${project.id}`}
                      onClick={() => {
                        onClose();
                        scrollToTop();
                      }}
                      className="block p-3 rounded-lg hover:bg-gray-100 dark:hover:bg-gray-800 transition-colors active:bg-gray-200 dark:active:bg-gray-700"
                    >
                      <div className="flex items-start gap-3">
                        <FolderGit2 className="w-5 h-5 text-primary dark:text-primary-light flex-shrink-0 mt-1" />
                        <div>
                          <h4 className="font-medium text-neutral-dark dark:text-white mb-1">
                            {project.title}
                          </h4>
                          <p className="text-sm text-neutral-dark/70 dark:text-white/70 line-clamp-2">
                            {project.description}
                          </p>
                        </div>
                      </div>
                    </Link>
                  ))}
                </div>
              </div>
            )}
        </div>
      )}
    </div>
  );
}
