import { Search as SearchIcon, X, ChevronLeft } from 'lucide-react';

interface SearchInputProps {
  query: string;
  setQuery: (query: string) => void;
  selectedType: 'all' | 'article' | 'project';
  setSelectedType: (type: 'all' | 'article' | 'project') => void;
  onClose: () => void;
  isMobile: boolean;
}

export default function SearchInput({
  query,
  setQuery,
  selectedType,
  setSelectedType,
  onClose,
  isMobile,
}: SearchInputProps) {
  return (
    <div className="sticky top-0 z-10 bg-white dark:bg-neutral-dark border-b border-gray-200 dark:border-gray-800">
      <div className="p-4 flex items-center gap-3">
        {isMobile && (
          <button
            onClick={onClose}
            className="p-2 -ml-2 hover:bg-gray-100 dark:hover:bg-gray-800 rounded-full transition-colors"
            aria-label="Close search"
          >
            <ChevronLeft className="w-5 h-5 text-neutral-dark/70 dark:text-white/70" />
          </button>
        )}
        <SearchIcon className="w-5 h-5 text-primary dark:text-primary-light" />
        <input
          id="search-input"
          type="search"
          placeholder="Search articles and projects..."
          value={query}
          onChange={e => setQuery(e.target.value)}
          className="flex-1 bg-transparent border-none outline-hidden text-lg text-neutral-dark dark:text-white placeholder-neutral-dark/50 dark:placeholder-white/50"
          // eslint-disable-next-line jsx-a11y/no-autofocus -- focus must enter the freshly opened search dialog
          autoFocus
          enterKeyHint="search"
        />
        {query && (
          <button
            onClick={() => setQuery('')}
            className="p-2 hover:bg-gray-100 dark:hover:bg-gray-800 rounded-full transition-colors"
            aria-label="Clear search"
          >
            <X className="w-5 h-5 text-neutral-dark/70 dark:text-white/70" />
          </button>
        )}
        {!isMobile && (
          <button
            onClick={onClose}
            className="p-2 hover:bg-gray-100 dark:hover:bg-gray-800 rounded-full transition-colors"
            aria-label="Close search"
          >
            <X className="w-5 h-5 text-neutral-dark/70 dark:text-white/70" />
          </button>
        )}
      </div>

      <div className="px-4 pb-4 flex gap-2">
        {['all', 'article', 'project'].map(type => (
          <button
            key={type}
            onClick={() => setSelectedType(type as 'all' | 'article' | 'project')}
            className={`px-3 py-1.5 rounded-full text-sm transition-colors ${
              selectedType === type
                ? 'bg-primary text-white'
                : 'bg-gray-100 dark:bg-gray-800 text-neutral-dark dark:text-white hover:bg-gray-200 dark:hover:bg-gray-700'
            }`}
          >
            {type.charAt(0).toUpperCase() + type.slice(1)}s
          </button>
        ))}
      </div>
    </div>
  );
}
