import { Location } from 'react-router-dom';

import navigationContent from '../../content/navigation.json';

import NavLink from './NavLink';

interface DesktopNavProps {
  location: Location;
}

export default function DesktopNav({ location }: DesktopNavProps) {
  return (
    <nav className="hidden md:flex items-center space-x-2" role="navigation">
      {navigationContent.links.map(link => (
        <NavLink
          key={link.href}
          href={link.href}
          isActive={
            link.href === '/' ? location.pathname === '/' : location.pathname.startsWith(link.href)
          }
        >
          {link.label}
        </NavLink>
      ))}
    </nav>
  );
}
