import { motion, AnimatePresence } from 'framer-motion';
import { useState, useEffect } from 'react';

import { useSearch } from '../../hooks/useSearch';

import SearchFooter from './SearchFooter';
import SearchInput from './SearchInput';
import SearchResultsList from './SearchResultsList';

interface SearchDialogProps {
  isOpen: boolean;
  onClose: () => void;
}

export default function SearchDialog({ isOpen, onClose }: SearchDialogProps) {
  const [query, setQuery] = useState('');
  const { search, results, isLoading, error } = useSearch();
  const [selectedType, setSelectedType] = useState<'all' | 'article' | 'project'>('all');
  const [isMobile] = useState(() => window.innerWidth < 768);

  // Debounced search
  useEffect(() => {
    if (!query.trim()) return;
    const handler = setTimeout(() => {
      search(query, selectedType === 'all' ? undefined : selectedType);
    }, 300);
    return () => clearTimeout(handler);
  }, [query, selectedType, search]);

  // Reset state when dialog closes
  useEffect(() => {
    if (!isOpen) {
      // eslint-disable-next-line react-hooks/set-state-in-effect -- intentional reset on close; effect observes every close path
      setQuery('');
      setSelectedType('all');
    }
  }, [isOpen]);

  // Handle keyboard shortcuts
  useEffect(() => {
    const handleKeyDown = (e: KeyboardEvent) => {
      if (e.key === 'Escape') onClose();
      if ((e.metaKey || e.ctrlKey) && e.key === 'k') {
        e.preventDefault();
        if (!isOpen) document.getElementById('search-input')?.focus();
      }
    };
    document.addEventListener('keydown', handleKeyDown);
    return () => document.removeEventListener('keydown', handleKeyDown);
  }, [isOpen, onClose]);

  return (
    <AnimatePresence>
      {isOpen && (
        <>
          <motion.div
            initial={{ opacity: 0 }}
            animate={{ opacity: 1 }}
            exit={{ opacity: 0 }}
            className="fixed inset-0 bg-black/40 backdrop-blur-sm z-50"
            onClick={onClose}
          />
          <motion.div
            initial={isMobile ? { y: '100%' } : { opacity: 0, scale: 0.95, y: -20 }}
            animate={isMobile ? { y: 0 } : { opacity: 1, scale: 1, y: 0 }}
            exit={isMobile ? { y: '100%' } : { opacity: 0, scale: 0.95, y: -20 }}
            className={`fixed z-50 bg-white dark:bg-neutral-dark overflow-hidden ${
              isMobile
                ? 'inset-x-0 bottom-0 rounded-t-xl max-h-[85vh]'
                : 'top-[15vh] left-1/2 -translate-x-1/2 w-full max-w-2xl rounded-xl shadow-2xl'
            }`}
            role="dialog"
            aria-modal="true"
            aria-labelledby="search-title"
          >
            <SearchInput
              query={query}
              setQuery={setQuery}
              selectedType={selectedType}
              setSelectedType={setSelectedType}
              onClose={onClose}
              isMobile={isMobile}
            />
            <SearchResultsList
              results={results}
              isLoading={isLoading}
              error={error}
              query={query}
              selectedType={selectedType}
              onClose={onClose}
            />
            {!isMobile && <SearchFooter />}
          </motion.div>
        </>
      )}
    </AnimatePresence>
  );
}
