import { createClient } from '@supabase/supabase-js';
import type { RealtimePostgresChangesPayload } from '@supabase/supabase-js';

import { toast } from '../../components/common/Toast';
import { emitEvent, type EventMap } from '../events';

import type { Database } from './types';

// Get environment variables based on context
const supabaseUrl =
  typeof window !== 'undefined'
    ? import.meta.env.VITE_SUPABASE_URL
    : process.env.SUPABASE_DATABASE_URL;

const supabaseKey =
  typeof window !== 'undefined'
    ? import.meta.env.VITE_SUPABASE_ANON_KEY
    : process.env.SUPABASE_SERVICE_ROLE_KEY;

if (!supabaseUrl || !supabaseKey) {
  throw new Error('Missing required Supabase environment variables');
}

// Configure Supabase client with improved error handling and retries
export const supabase = createClient<Database>(supabaseUrl, supabaseKey, {
  auth: {
    persistSession: true,
    autoRefreshToken: true,
    detectSessionInUrl: true,
    flowType: 'pkce',
  },
  global: {
    headers: { 'x-application-name': 'rewi-re' },
    fetch: async (url, init) => {
      const maxRetries = 3;
      const baseDelay = 1000; // 1 second

      for (let attempt = 0; attempt < maxRetries; attempt++) {
        try {
          // Create headers object from existing init headers
          const headers = new Headers(init?.headers);
          headers.set('Cache-Control', 'public, max-age=600'); // 10 minute cache

          const response = await fetch(url, {
            ...init,
            headers,
            // Add timeout to prevent hanging requests
            signal: AbortSignal.timeout(10000), // 10 second timeout
          });

          if (!response.ok) {
            throw new Error(`HTTP error! status: ${response.status}`);
          }

          return response;
        } catch (error) {
          const isLastAttempt = attempt === maxRetries - 1;
          if (isLastAttempt) {
            console.error('Supabase fetch error:', error);
            throw error;
          }

          // Exponential backoff
          const delay = baseDelay * Math.pow(2, attempt);
          await new Promise(resolve => setTimeout(resolve, delay));
        }
      }

      throw new Error('Max retries exceeded');
    },
  },
  db: {
    schema: 'public',
  },
  realtime: {
    params: {
      eventsPerSecond: 2,
      realtimeTimeout: 60000,
    },
  },
});

// Enable real-time subscriptions for specific tables
export const enableRealtimeSubscriptions = () => {
  const subscriptions: ReturnType<typeof supabase.channel>[] = [];

  const createSubscription = (table: string, eventTypes: string[] = ['*']) => {
    try {
      const channel = supabase.channel(`${table}-changes`, {
        config: {
          broadcast: { ack: true },
        },
      });

      eventTypes.forEach(eventType => {
        channel.on(
          // @ts-expect-error -- Supabase channel.on overloads don't support dynamic event strings
          'postgres_changes',
          {
            event: eventType,
            table,
            schema: 'public',
          },
          (payload: RealtimePostgresChangesPayload<Record<string, unknown>>) => {
            // Only dispatch event if payload is valid
            if (!payload || !payload.eventType) return;

            const eventName = `${table}-updated` as keyof EventMap;
            emitEvent(eventName, {
              type: payload.eventType,
              new: payload.new as Record<string, unknown>,
              old: (payload.old ?? {}) as Record<string, unknown>,
            });

            // Show toast notification for important changes
            if (eventType !== 'SELECT' && payload.eventType) {
              const action =
                eventType === 'INSERT' ? 'added' : eventType === 'UPDATE' ? 'updated' : 'removed';
              toast.success(`Content ${action} successfully`);
            }
          }
        );
      });

      channel.subscribe(status => {
        if (status === 'SUBSCRIBED') {
          console.log(`Subscribed to ${table} changes`);
        } else if (status === 'CHANNEL_ERROR') {
          console.warn(`Channel error for ${table}, will retry automatically`);
          // Supabase client will automatically attempt to reconnect
        }
      });

      return channel;
    } catch (error) {
      console.warn(`Could not create subscription for ${table}:`, error);
      return null;
    }
  };

  // Create subscriptions for all tables
  const channels = ['content', 'tags', 'skills', 'skill_categories', 'awards', 'design_tokens']
    .map(table => createSubscription(table))
    .filter((ch): ch is NonNullable<typeof ch> => ch !== null);

  subscriptions.push(...channels);

  return () => {
    subscriptions.forEach(subscription => {
      try {
        if (subscription && subscription.unsubscribe) {
          subscription.unsubscribe();
        }
      } catch (error) {
        console.error('Error unsubscribing:', error);
      }
    });
  };
};

// Test connection with retries
export async function testSupabaseConnection() {
  const maxRetries = 3;
  const baseDelay = 1000;

  for (let attempt = 0; attempt < maxRetries; attempt++) {
    try {
      const { error } = await supabase.from('tags').select('count').limit(1);
      if (error) throw error;
      return true;
    } catch (error) {
      const isLastAttempt = attempt === maxRetries - 1;
      if (isLastAttempt) {
        console.error('Supabase connection test failed:', error);
        return false;
      }

      const delay = baseDelay * Math.pow(2, attempt);
      await new Promise(resolve => setTimeout(resolve, delay));
    }
  }

  return false;
}

export const cleanupSupabase = async () => {
  try {
    await supabase.removeAllChannels();
  } catch (error) {
    console.error('Error cleaning up Supabase channels:', error);
  }
};
